//! 🔺️ reorder-buffer-views leaf-owned typed sparse operation diff.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfBufferView;
use crate::artifacts::gltf::schema::diff::GltfDiff;
use crate::artifacts::gltf::schema::mutations::reorder_buffer_views::mutation::{apply, validate, GltfReorderBufferViewsPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{buffer_views_op, family_diff, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.reorder-buffer-views.v1";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfReorderBufferViewsOperation { Insert { position: usize, item: GltfBufferView }, Delete { index: usize, removed: GltfBufferView }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfReorderBufferViewsDiff { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfReorderBufferViewsPayload, pub operation: GltfReorderBufferViewsOperation }
fn operation(payload: &GltfReorderBufferViewsPayload, base: &GltfSnapshot) -> GltfReorderBufferViewsOperation { GltfReorderBufferViewsOperation::Reorder { order: payload.order.clone() } }
fn touched_paths(payload: &GltfReorderBufferViewsPayload) -> Vec<String> { payload.order.iter().map(|index| format!("document/bufferViews/{}", index)).chain(std::iter::empty()).collect() }
pub fn validate_diff(diff: &GltfReorderBufferViewsDiff, base: &GltfSnapshot) -> Result<(), GltfTopLevelMutationRejection> { if diff.id != ID || diff.version != 1 { return Err(reject("gltf.mutation.invalid-diff-envelope", "diff", "descriptor identity does not match")); } if diff.touched_paths != touched_paths(&diff.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "diff/touchedPaths", "paths must be concrete payload-derived locations")); } validate(&diff.payload, base)?; if diff.operation != operation(&diff.payload, base) { return Err(reject("gltf.mutation.invalid-sparse-operation", "diff/operation", "operation must equal the direct typed delta")); } Ok(()) }
pub fn apply_diff(diff: &GltfReorderBufferViewsDiff, base: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_diff(diff, base)?; let mut next = base.clone(); let operation = &diff.operation; match operation { GltfReorderBufferViewsOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::BufferViews, &Change::Insert(*position))?; next.document.buffer_views.insert(*position, item.clone());  }, GltfReorderBufferViewsOperation::Delete { index, .. } => { buffer_views_op(&mut next, GltfTopLevelFamily::BufferViews, *index, None, None)?;  }, GltfReorderBufferViewsOperation::Move { index, position } => { buffer_views_op(&mut next, GltfTopLevelFamily::BufferViews, *index, Some(*position), None)?;  }, GltfReorderBufferViewsOperation::Reorder { order } => { buffer_views_op(&mut next, GltfTopLevelFamily::BufferViews, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(diff: &GltfReorderBufferViewsDiff) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(diff).map_err(|error| reject("gltf.mutation.encode-failed", "diff", error.to_string())) }
pub fn derive(payload: &GltfReorderBufferViewsPayload, base: &GltfSnapshot) -> Result<GltfReorderBufferViewsDiff, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfReorderBufferViewsDiff { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
pub fn derive_transitional_gltf_diff(payload: &GltfReorderBufferViewsPayload, base: &GltfSnapshot) -> Result<GltfDiff, GltfTopLevelMutationRejection> { let next = apply(payload, base)?; Ok(family_diff(GltfTopLevelFamily::BufferViews, base, &next)) }
